			/**
			 * 데이터 저장 서브미션 호출
			 */
			function doSave(){
				
				// 데이터 변경사항이 없을시 "변경된 데이터가 없습니다" 출력
				if (!util.Grid.isModified(app, "grdId", "MSG")) return false;
				
				// 그리드 내 컬럼 유효성 체크
				if (!util.validate(app, "grdId")) return false;
				
				// 저장 서브미션 호출
				util.Submit.send(app, "subSave", function(pbSuccess){
					if(pbSuccess){
						doList("save");
					}
				});
			}

			/**
			 * 채팅 테이블 셋팅
			 */
			function setChttList(){
			    var dsListChatWait = app.lookup("dsListChttWaitNocs");
			    var grp15 = app.lookup("grp31");
			    var childCnt = grp15.getChildrenCount();
			    
			    for( var i=childCnt-1; i > 0; i--) {
			        var childControl = grp15.getLastChild();
			        grp15.removeChild(childControl);
			    }
			    
			    childCnt = dsListChatWait.getRowCount();
			    for( var i=0; i < childCnt; i++) {
			        var rec = dsListChatWait.getRow(i);
			                
			                var group_2 = new cpr.controls.Container("grpChild");
			                // Layout
			                var formLayout_1 = new cpr.controls.layouts.FormLayout();
			                formLayout_1.scrollable = false;
			                formLayout_1.topMargin = "0px";
			                formLayout_1.rightMargin = "0px";
			                formLayout_1.bottomMargin = "0px";
			                formLayout_1.leftMargin = "0px";
			                formLayout_1.horizontalSpacing = "0px";
			                formLayout_1.verticalSpacing = "0px";
			                formLayout_1.setColumns(["1fr"]);
			                formLayout_1.setRows(["25px", "1fr"]);
			                formLayout_1.setUseRowShade(0, true);
			                group_2.setLayout(formLayout_1);
			                (function(container) {
			                    var output_1 = new cpr.controls.Output("opt1");
			                output_1.value = rec.getValue("RSPNS_CN")+"분";
			                output_1.style.setClasses(["label"]);
			                output_1.style.css({
			                    "text-align": "center"
			                });
			                container.addChild(output_1, {
			                    "colIndex": 0,
			                "rowIndex": 0
			                });
			                var output_2 = new cpr.controls.Output("opt2");
			                output_2.value = rec.getValue("MCOUNT")+"건";
			                output_2.style.css({
			                    "text-align": "center"
			                });
			                container.addChild(output_2, {
			                    "colIndex": 0,
			                "rowIndex": 1,
			                "colSpan": 1,
			                "rowSpan": 1
			                    });
			                })(group_2);
			                grp15.addChild(group_2, {
			                    "width": "100px",
			                "height": "50px"
			                    });
			    }
			}
